const s = $input.first().json;
const n = (v) => Number(v) || 0;

const total = n(s.total);
const autoRate = total ? Math.round((n(s.auto_posted) / total) * 100) : 0;

const subject = `Weekly invoice report: ${total} invoices, ${autoRate}% auto-posted`;

const body = [
  'WEEKLY INVOICE REPORT (last 7 days)',
  '-----------------------------------',
  `Invoices received:     ${total}`,
  `Auto-posted:           ${n(s.auto_posted)} (${autoRate}%)`,
  `Approved by human:     ${n(s.approved)}`,
  `Rejected by human:     ${n(s.rejected)}`,
  `Still waiting review:  ${n(s.pending_now)}`,
  `Duplicates blocked:    ${n(s.duplicates)}`,
  '',
  `Value posted:          ${n(s.value_posted).toFixed(2)}`,
  `Average confidence:    ${n(s.avg_confidence)}`,
  '',
  `LLM spend:             $${n(s.llm_cost).toFixed(4)}`,
  `Workflow errors:       ${n(s.errors)}`,
].join('\n');

return [{ json: { subject, body } }];
